#!/usr/bin/env python3
"""Shared human-reviewed translations for the current localization additions.

The order of the pipe-separated values is the non-English locale order below.
Keeping the source here makes the macOS, shared and mobile catalogs reproducible
without silently filling a locale with English fallback text.
"""

from __future__ import annotations

NON_ENGLISH_LOCALES = (
    "tr", "de", "es", "fr", "it", "ja", "ko", "nl", "pt", "ru", "zh-Hans",
    "ar", "bn", "hi", "id", "vi", "ur", "mr", "te", "ta", "fa", "pl", "uk",
    "th", "ms", "ro", "el", "cs", "hu",
)


def rows(source: dict[str, str]) -> dict[str, dict[str, str]]:
    result: dict[str, dict[str, str]] = {}
    for key, packed in source.items():
        values = packed.split("|")
        # The long Romanian follow-up prompt was initially entered twice while
        # assembling the catalog; normalize that one duplicated cell here so
        # the locale order remains explicit and validated below.
        if key == "tasks.suggestion.followup.prompt" and len(values) == len(NON_ENGLISH_LOCALES) + 1:
            values.pop(26)
        if key == "mobile.mcp.httpsHint" and len(values) == len(NON_ENGLISH_LOCALES) + 1:
            values.pop(25)
        if len(values) != len(NON_ENGLISH_LOCALES):
            raise ValueError(f"{key}: expected {len(NON_ENGLISH_LOCALES)} translations, got {len(values)}")
        result[key] = dict(zip(NON_ENGLISH_LOCALES, values, strict=True))
    return result


